package com.estoqueinteligente.report;
import java.util.List;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/reports") public class ReportController{private final ReportService service;public ReportController(ReportService service){this.service=service;}@GetMapping("/stock")public List<StockReportResponse> stock(){return service.stock();}@GetMapping("/low-stock")public List<LowStockReportResponse> lowStock(){return service.lowStock();}@GetMapping("/expiring")public List<ExpiringReportResponse> expiring(){return service.expiring();}@GetMapping("/expired")public List<ExpiredReportResponse> expired(){return service.expired();}@GetMapping("/purchase-suggestion")public List<PurchaseSuggestionResponse> purchaseSuggestion(){return service.purchaseSuggestion();}}
